#include <bits/stdc++.h>
using namespace std;

long long power(long long base, long long exp, long long mod) {
    long long result = 1;
    long long b = base % mod;
    long long e = exp;
    while (e > 0) {
        if (e & 1) {
            result = (result * b) % mod;
        }
        b = (b * b) % mod;
        e >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    const long long modulus = 998244353;
    long long n, k;
    cin >> n >> k;

    vector<long long> factorials(200001);
    factorials[0] = 1;
    for (int i = 1; i <= 200000; i++) {
        factorials[i] = (factorials[i - 1] * i) % modulus;
    }

    long long answer = 0;
    for (int i = 0; i < n - k; i++) {
        long long numerator = factorials[n - k];
        long long invI = power(factorials[i], modulus - 2, modulus);
        long long invNMinusKMinusI = power(factorials[n - k - i], modulus - 2, modulus);
        long long comb = (numerator * invI) % modulus;
        comb = (comb * invNMinusKMinusI) % modulus;
        long long val = power(n - k - i, n, modulus);
        if (i % 2 == 0) {
            answer = (answer + comb * val) % modulus;
        } else {
            answer = (answer - comb * val + modulus) % modulus;
        }
    }

    if (k >= n) {
        cout << 0 << "\n";
    } else {
        if (k != 0) {
            answer = (answer * 2) % modulus;
        }
        answer = (answer * factorials[n]) % modulus;
        answer = (answer * power(factorials[k], modulus - 2, modulus)) % modulus;
        answer = (answer * power(factorials[n - k], modulus - 2, modulus)) % modulus;
        cout << answer << "\n";
    }
    return 0;
}
